import { isPlainObject } from "./lib/agent/mcp/oauth/metadata-cache";
import { secureOAuthUrl } from "./lib/agent/mcp/oauth/url";

const params = new URLSearchParams(location.search);
const state = params.get("state");
const callback =
  location.pathname.endsWith("mcp-oauth-callback.html") ||
  params.has("code") ||
  params.has("error");
history.replaceState(null, "", location.pathname);
const status = document.getElementById("oauth-status");
const fail = (message: string): void => {
  if (status) status.textContent = message;
};

if (!state || !/^[A-Za-z0-9_-]{20,256}$/.test(state)) {
  fail("Open MCP sign-in from OfficeAI settings.");
} else {
  const usingOffice = state.startsWith("office_");
  const channel =
    !usingOffice && typeof BroadcastChannel !== "undefined"
      ? new BroadcastChannel(`officeai-mcp-oauth-${state}`)
      : undefined;
  const message: Record<string, string> = {
    type: callback ? "officeai-oauth-callback" : "officeai-oauth-ready",
    state,
  };
  if (callback) {
    for (const field of ["code", "iss", "error"]) {
      const value = params.get(field);
      if (value !== null && value.length <= 4096) message[field] = value;
    }
  }
  const receive = (data: unknown): void => {
    if (
      callback ||
      !isPlainObject(data) ||
      data.type !== "officeai-oauth-start" ||
      data.state !== state
    )
      return;
    const url = secureOAuthUrl(data.url);
    if (
      !url ||
      url.searchParams.get("state") !== state ||
      url.searchParams.get("code_challenge_method") !== "S256"
    ) {
      fail("The sign-in request was rejected.");
      return;
    }
    window.removeEventListener("message", onMessage);
    channel?.close();
    location.replace(url.href);
  };
  const onMessage = (event: MessageEvent): void => {
    if (event.origin === location.origin && event.source === window.opener)
      receive(event.data);
  };
  window.addEventListener("message", onMessage);
  if (channel) channel.onmessage = (event) => receive(event.data);
  if (!usingOffice) {
    channel?.postMessage(message);
    window.opener?.postMessage(message, location.origin);
  } else {
    const initializeOffice = (): void => {
      Office.onReady(() => {
        if (!Office.context?.ui?.messageParent) {
          fail("Office dialog messaging is unavailable.");
          return;
        }
        if (!callback) {
          Office.context.ui.addHandlerAsync(
            Office.EventType.DialogParentMessageReceived,
            (event: { message: string; origin?: string }) => {
              if (event.origin !== location.origin) return;
              let data: unknown;
              try {
                data = JSON.parse(event.message);
              } catch {
                fail("The sign-in request was invalid.");
                return;
              }
              receive(data);
            },
            (result) => {
              if (result.status === Office.AsyncResultStatus.Succeeded) {
                Office.context.ui.messageParent(JSON.stringify(message), {
                  targetOrigin: location.origin,
                });
              } else {
                fail("Office could not initialize secure dialog messaging.");
              }
            },
          );
        } else {
          Office.context.ui.messageParent(JSON.stringify(message), {
            targetOrigin: location.origin,
          });
        }
      });
    };
    if (typeof Office !== "undefined") {
      initializeOffice();
    } else {
      const script = document.createElement("script");
      script.src = "https://appsforoffice.microsoft.com/lib/1/hosted/office.js";
      script.referrerPolicy = "no-referrer";
      script.onload = initializeOffice;
      script.onerror = () =>
        fail("Office.js could not be loaded for this dialog.");
      document.head.append(script);
    }
  }
  if (callback) {
    channel?.close();
    fail("Authorization returned. You can close this window.");
  }
}
